-- GENERATED by `python3 -m analytics render evidence` (analytics/specs/ceo_weekly_pulse.yml#loss_making_channels; inputs sha256 f86822d969fa5fa3). Do not edit by hand.
SELECT COUNT(*) AS loss_making_channels
FROM (
    SELECT e.channel_key
    FROM main_marts.fact_order_economics e
    JOIN main_marts.fact_orders o ON e.order_id = o.order_id
    WHERE e.scope_sales
      AND e.has_cogs
      AND o.is_active_order
      AND o.ordered_at >= timezone('Asia/Ho_Chi_Minh', CAST(CAST(date_trunc('week', (CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1)) AS DATE) AS TIMESTAMP))
      AND o.ordered_at < timezone('Asia/Ho_Chi_Minh', CAST(((CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1) + 1) AS TIMESTAMP))
    GROUP BY e.channel_key
    HAVING SUM(e.channel_net_profit) < 0
) loss_channels
